#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSaleItemsI(std::vector<std::vector<int>>& items, int budget) {
        int n = items.size();
        int cheapest = 2e9;
        for (const auto& it : items) cheapest = std::min(cheapest, it[1]);
        int maxAns = budget / cheapest;
        for (int i = 0; i < n; ++i) {
            int f_i = items[i][0], p_i = items[i][1];
            if (p_i <= budget) {
                int freeCount = 1;
                for (int j = 0; j < n; ++j) {
                    if (j != i && items[j][0] % f_i == 0) freeCount++;
                }
                int remBudget = budget - p_i;
                maxAns = std::max(maxAns, freeCount + remBudget / cheapest);
            }
        }
        return maxAns;
    }
};

class Solution {
    public int maxSaleItemsI(int[][] items, int budget) {
        int n = items.length;
        int cheapest = Integer.MAX_VALUE;
        for (int[] it : items) cheapest = Math.min(cheapest, it[1]);
        int maxAns = budget / cheapest;
        for (int i = 0; i < n; i++) {
            int f_i = items[i][0], p_i = items[i][1];
            if (p_i <= budget) {
                int freeCount = 1;
                for (int j = 0; j < n; j++) {
                    if (j != i && items[j][0] % f_i == 0) freeCount++;
                }
                int remBudget = budget - p_i;
                maxAns = Math.max(maxAns, freeCount + remBudget / cheapest);
            }
        }
        return maxAns;
    }
}

